def e(x): return html.escape(str(x),quote=True)
def a(path,label):return '<a href="'+e(path)+'">'+e(label)+'</a>'
def p(x):return '<p>'+x+'</p>'
def sec(i,h,b):return {'id':i,'title':h,'html':b}
def ul(xs):return '<ul>'+''.join('<li>'+x+'</li>' for x in xs)+'</ul>'
def table(headers,rows):return '<div class="byf-answer-table" role="region" tabindex="0" aria-label="'+e(headers[0])+' comparison"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+c+'</th>') if j==0 else '<td>'+c+'</td>' for j,c in enumerate(r))+'</tr>' for r in rows)+'</tbody></table></div>'
SCENARIOS=[]
def worked(label,flight,stages,buffer=180):
 f=datetime.fromisoformat(flight);target=f-timedelta(minutes=buffer);total=sum(n for _,n in stages);leave=target-timedelta(minutes=total)
 SCENARIOS.append({'label':label,'flightJST':flight,'bufferMinutes':buffer,'airportReadyJST':target.isoformat(timespec='minutes'),'stages':[{'label':s,'minutes':m} for s,m in stages],'totalBeforeAirportReadyMinutes':total,'endSightseeingJST':leave.isoformat(timespec='minutes')})
 return [label, ' + '.join(str(n) for _,n in stages)+' = <strong>'+str(total)+' min</strong>', '<strong>'+leave.strftime('%H:%M')+'</strong>']
def example_table(rows,flight='21:00',target='18:00'):
 return p('For a <strong>'+flight+' international flight</strong>, these examples protect an <strong>'+target+' terminal-ready target</strong>. The components below are deliberately rounded planning allowances, not advertised train running times or departures you can book. They assume you are already at the collection point when sightseeing ends; travel back to a distant hotel is additional.')+table(['Example and component order','Calculation','End sightseeing / begin bag collection'],rows)
def earlier():return p('<strong>If your airline asks you to arrive earlier:</strong> use that earlier terminal-ready time. The current planner uses a fixed three-hour international allowance and has no field for an earlier airline target. Do not accept a suggested route unless it also fits the earlier requirement; shorten it or go directly to the airport.')
G={}
def add(path,title,description,lead,sections,refs,airport,related):G[path]={'title':title,'description':description,'lead':lead,'sections':sections,'refs':refs,'airport':airport,'related':related}
# Tokyo checkout: make the baggage decision change the itinerary.
add('after-hotel-checkout-tokyo','What to Do After Hotel Checkout in Tokyo Before a Flight',
 'Choose a final Tokyo stop around your bags and airport route, with named station storage, a Haneda-versus-Narita comparison and worked leave-by times.',
 'After checkout, the best last stop is often the one on the same side of Tokyo as your bags and airport train. A relaxed meal in Shinagawa can be more useful than another famous district if the suitcase is waiting there.',[
 sec('bag-first','Choose the bag location before choosing the neighborhood',table(['Where the bags will be','A practical final stop','What makes it work'],[
 ('Hotel near Shinjuku','A nearby meal, Shinjuku shops or Hanazono Shrine','Finish near the hotel, collect once, then take the airport route. Going to Ginza and returning west adds a second city journey.'),('Shinagawa','A station-side meal or ecute purchase if you already have valid JR gate access','Collect bags, then reach the separate Keikyu gates for Haneda. ecute is inside JR gates; it is not an outside-gate waiting room.'),('Tokyo Station','Marunouchi facade or Tokyo Character Street','Stay on the correct side of the station for storage and your train. The Marunouchi and Yaesu sides are not interchangeable.'),('Ueno / Keisei-Ueno','A short Ameyoko pass or Ueno Park stop','Useful for a Keisei airport return. JR Ueno and Keisei-Ueno are separate stations; collect near the operator you will use.')])+p('Hotel storage may be convenient, but ask about the collection deadline and whether staff can accept the actual bag. Do not assume every hotel offers free storage after checkout.')),
 sec('tokyo-storage','One documented Tokyo Station option',p('GRANSTA lists a B1 cloakroom <strong>inside JR gates</strong> and a 1F JR EAST Travel Service Center cloakroom <strong>outside the gates</strong>. Its published S/M/L fees are ¥500/¥1,000/¥2,000 per item. The B1 listing gives 08:30–21:00 and a separate same-day storage note of “until 20:30”; the outside-gate counter lists 08:30–20:00. Plan collection before the applicable cutoff rather than treating the building’s closing time as spare sightseeing time.')+p('The operator’s page is dated 23 May 2025; size/weight limits and current counter terms still apply. '+a(S['gransta'][0],'Open the storage map and published conditions')+'. An available small locker is not a substitute for a compartment that fits your suitcase.')),
 sec('airport-choice','Haneda and Narita lead to different last-day choices',p('For Haneda, Shinagawa → Keikyu or the Hamamatsucho monorail corridor can keep the route compact. For Narita, compare a reserved Narita Express from a station on its route with Keisei from Keisei-Ueno or Nippori. Choose the departure station before lunch, not after collecting a heavy bag.')+p('If your Narita bags are still in Shinjuku, an eastern Tokyo stop is only useful when the return to Shinjuku is budgeted. Narita town is a separate excursion; do not add it merely because its name matches the airport.')),
 sec('tokyo-calculation','See how the luggage location changes the hard stop',example_table([
 worked('Haneda: Shinagawa pickup 20 + station/wait 15 + rail allowance 30 + terminal navigation 20','2026-11-20T21:00',[('Bag pickup',20),('Station and waiting',15),('Rail allowance',30),('Terminal navigation',20)]),
 worked('Haneda: Shinjuku pickup 20 + station approach 15 + wait 15 + rail/connections 65 + terminal navigation 20','2026-11-20T21:00',[('Bag pickup',20),('Station approach',15),('Waiting',15),('Rail and connections',65),('Terminal navigation',20)])])+p('The Shinagawa example ends sightseeing at 16:35; the Shinjuku example at 15:45. This comparison explains the effect of location, not which train to catch. A real hotel-to-station walk or service disruption can require an earlier finish.')),
 sec('checkout-fallback','When the final stop should simply be lunch',p('If storage is full, rain makes the walk unpleasant or the hotel pickup has slipped, choose a seated meal near the departure station and keep the case with you. Tokyo Station food shopping, an outside-gate Shinagawa meal or the airport itself are complete options. You do not need another attraction for the day to feel finished.')+earlier())
 ],['gransta','keikyu','nex','skyliner'],'HND',[('/places/shinagawa/','Shinagawa meal and gate-side choices'),('/places/tokyo-character-street/','Tokyo Character Street inside the station complex'),('/guides/luggage-before-flight-japan/','Compare hotel, station and airport storage')])
# Tokyo late flight: distinguish late flight from late opening.
add('before-late-flight-tokyo','What to Do Before a Late Flight from Tokyo',
 'Use a late Tokyo flight for a realistic final day: morning markets, an afternoon near your bags and a clear evening airport departure, including midnight dates.',
 'A late flight can give you a good final day, but it does not make every attraction a late-evening option. Put opening-sensitive places first, then finish near the luggage and the airport route.',[
 sec('late-day','Build a day that gets simpler toward the end',table(['Part of the day','A concrete choice','Keep this boundary'],[
 ('Morning','Tsukiji Outer Market for one meal, or Sensoji for the temple','Tsukiji shop hours vary; Sensoji’s main hall and Nakamise stores have different hours.'),('Afternoon','One shopping stop near the collection point: Ginza, Tokyo Station or Shinagawa','Avoid another cross-city journey after packing purchases.'),('Final city stop','A meal or coffee near the station used for the airport','This is where you can shorten the day if the earlier visit runs late.'),('Airport','Find the counter and gate first, then use genuinely spare time','A lounge or duty-free stop is optional; it cannot replace airline procedures.')])+p('This is an order of decisions, not a recommendation to do all the named neighborhoods. Choose one morning area and one nearby final stop.')),
 sec('late-hnd-nrt','Choose the last station for the airport you actually use',p('<strong>Haneda:</strong> if your bags are in Shinagawa, keep the last meal there and follow Keikyu signs after collection. If they are near Tokyo Station, compare the route via Shinagawa with the monorail corridor via Hamamatsucho from your actual gate or hotel.')+p('<strong>Narita:</strong> a reserved airport service needs a real departure, not just a quick journey advertised online. Use JR East’s Narita Express timetable from the station you can reach, or Keisei’s service from the Ueno/Nippori corridor. A reservation does not include walking back to the hotel.')),
 sec('late-hours','Why a 21:00 flight does not mean sightseeing until 18:00',example_table([worked('Collect bags 20 + walk/platform 15 + wait 20 + rail/connections 60 + terminal navigation 20','2026-11-20T21:00',[('Bag pickup',20),('Station approach',15),('Waiting',20),('Rail and connections',60),('Terminal navigation',20)])])+p('In this example sightseeing ends at 15:45, even though the flight is at 21:00. If the chosen route is shorter, the extra time can remain as a relaxed break; it does not need to become another district.')),
 sec('midnight-flight','A 00:30 departure means the previous evening',p('A ticket for <strong>21 November at 00:30</strong> has a three-hour airport-ready target of <strong>20 November at 21:30</strong>. Enter 21 November as the flight date and 20 November as the free-time date. Do not travel to the airport on the evening of 21 November.')+p('Using 20 minutes for pickup and 90 minutes for the complete journey, sightseeing ends at <strong>19:40 on 20 November</strong>. Those are example allowances; an evening hotel detour can move the cutoff earlier.')),
 sec('late-cancel','What to drop when the day slips',ul(['First drop a second shopping district. Keep the visit close to the storage point.','If a restaurant has a long queue, use takeaway or eat at the airport; do not extend the leave-by time.','If trains are disrupted, leave the optional activity and find an operating airport route. Do not rely on the planner as a live disruption service.'])+earlier())
 ],['keikyu','nex','skyliner','hnd-dep'],'HND',[('/guides/haneda-airport-open-24-hours/','Haneda after midnight and before the first train'),('/places/tsukiji-outer-market/','Tsukiji opening times and a compact food visit'),('/guides/narita-departure-day/','Choose a last stop for Narita')])
