# Renderer preserves shared header/footer and current canonical identities.
def replace_metadata(text,path,row):
 title=e(row['title']);desc=e(row['description']);url=DOMAIN+'/'+path+'/'
 text=re.sub(r'<title>.*?</title>',f'<title>{title} — Before You Fly</title>',text,flags=re.S)
 for attr,val in [('name="description"',desc),('property="og:title"',title),('property="og:description"',desc),('property="og:url"',url)]:
  text=re.sub(r'(<meta '+attr+r' content=")[^"]*',lambda m:m[1]+val,text)
 text=re.sub(r'(<link rel="canonical" href=")[^"]*',lambda m:m[1]+url,text)
 text=re.sub(r'<!-- BYF:query-schema -->.*?<!-- /BYF:query-schema -->','',text,flags=re.S)
 text=re.sub(r'<script type="application/ld\+json">.*?</script>','',text,flags=re.S)
 schema=[{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':DOMAIN+'/'},{'@type':'ListItem','position':2,'name':'Guides','item':DOMAIN+'/guides/'},{'@type':'ListItem','position':3,'name':row['title'],'item':url}]},{'@context':'https://schema.org','@type':'Article','headline':row['title'],'description':row['description'],'dateModified':DATE,'mainEntityOfPage':url,'author':{'@type':'Organization','name':'Before You Fly','url':DOMAIN+'/about/'}}]
 text=text.replace('</head>',''.join('<script type="application/ld+json">'+json.dumps(x,ensure_ascii=False)+'</script>' for x in schema)+'</head>')
 if '/assets/query-guides.css' not in text:text=text.replace('</head>','<link rel="stylesheet" href="/assets/query-guides.css?v=20261117-1"></head>')
 else:text=re.sub(r'(/assets/query-guides.css\?v=)[^"&]+',r'\g<1>20261117-1',text)
 return text
for path,row in G.items():
 file=ROOT/path/'index.html';text=file.read_text()
 nav='<nav class="byf-answer-nav" aria-label="On this page">'+''.join(a('#'+s['id'],s['title']) for s in row['sections'])+'</nav>'
 body=''.join('<section id="'+e(s['id'])+'"><h2>'+s['title']+'</h2>'+s['html']+'</section>' for s in row['sections'])
 refs='<section id="guide-sources"><h2>Sources and what these times mean</h2>'+p('Guide reviewed 17 November 2026. Official sources establish the quoted facilities, access rules and service details. Calculations and rounded example allowances are our editorial planning models, not measured journeys, live departures or guaranteed queues. Older published storage-listing dates are identified in the text.')+ul([a(S[k][0],S[k][1]) for k in row['refs']])+'</section>'
