evidence={'reviewed':DATE,'scope':'13 English departure guides; source-linked official facts and distinct editorial decisions','pages':[{'path':'/'+path+'/','title':row['title'],'wordCountApprox':len(re.sub('<[^>]+>',' ',row['lead']+' '.join(s['html'] for s in row['sections'])).split()),'sourceIds':row['refs'],'sources':[{'url':S[k][0],'label':S[k][1],'checked':DATE} for k in row['refs']],'airportCTA':row['airport']} for path,row in G.items()],'scenarios':SCENARIOS,'sourceLimitations':['Storage listing dates are older than the review date and are explicitly disclosed.','No source confirms live locker/counter capacity or a passenger-specific queue.','KIX official content was retrieved with web search; automated direct HTTP can return 403.','No live departure, fee quote or firsthand visit is implied by an editorial calculation.']}
